use serde_json::Value;use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/g1-offset177";
const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-11-g1-offset177";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn files(p:&Path,base:&Path,out:&mut BTreeMap<String,String>){if p.is_dir(){for e in fs::read_dir(p).unwrap(){files(&e.unwrap().path(),base,out)}}else{out.insert(p.strip_prefix(base).unwrap().display().to_string(),hash(p));}}
fn main(){
 let pairs=[("primary32","primary 32-worker"),("primary16","primary 16-worker"),("Primary16","At 16 workers, 1×2"),("Merge54 at32","Merge 54×1 at 32"),("CPU10×","CPU 10×"),("sorted30 ranks9/20","30 sorted ratios at ranks 9/20"),("ranks14/15","ranks 14/15"),("1MiB","1 MiB"),("pair1","pair 1"),("primary32","primary 32-worker"),("unknown1.864%","unknown share 1.864%"),("least99.9%","least 99.9%"),("about0.34","about 0.34"),("OFFcopy1","OFF copy 1"),("OFFcopies0/2","OFF copies 0/2"),("remains1,600bytes","remains 1,600 bytes"),("Native130core+2prover+6cubic and generic97core tests","130 native core tests, two prover unit tests, six cubic tests and 97 generic core tests"),("checks19","checks 19"),("reader's102-versus97","reader's 102-versus-97"),("and945","and 945"),("advances52000→52027→52927→**52945**","advances 52,000 → 52,027 → 52,927 → **52,945**"),("reconstructs900","reconstructs 900"),("all31","all 31"),("Rust1.98.1","Rust 1.98.1"),("huge250/4999","huge 250/4999"),("and[artifact index]","and [artifact index]"),("workers≤","workers ≤"),("upper<1","upper < 1"),("uppers≤1.02","uppers ≤ 1.02"),("ON≤accepted×1.05+1 MiB","ON ≤ accepted × 1.05 + 1 MiB")];
 for p in[format!("{D}/README.md"),format!("{R}/finalize.rs")]{let mut s=fs::read_to_string(&p).unwrap();for(a,b)in pairs{s=s.replace(a,b);}fs::write(p,s).unwrap();}
 let p=format!("{R}/finalize.rs");let s=fs::read_to_string(&p).unwrap();let old="\"summary\":v[\"summary\"]";assert_eq!(s.matches(old).count(),1);let new="\"summary\":{let mut summary=v[\"summary\"].clone();summary.as_object_mut().unwrap().retain(|k,_| !k.starts_with(\"placement_\"));summary}";fs::write(&p,s.replace(old,new)).unwrap();fs::copy(&p,format!("{D}/artifacts/finalize.rs")).unwrap();
 let p=format!("{D}/artifacts/resource-rows.json");let mut rows:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();for row in rows.as_array_mut().unwrap(){row["summary"].as_object_mut().unwrap().retain(|k,_|!k.starts_with("placement_"));}fs::write(p,serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
 fs::copy(format!("{R}/polish-report.rs"),format!("{D}/artifacts/polish-report.rs")).unwrap();
 let mut all=BTreeMap::new();files(Path::new(&format!("{D}/artifacts")),Path::new(D),&mut all);all.insert("README.md".into(),hash(format!("{D}/README.md")));fs::write(format!("{D}/SHA256SUMS"),all.iter().map(|(p,h)|format!("{h}  {p}\n")).collect::<String>()).unwrap();
 println!("Polished prose; compact resource projection omits repeated affinity rows, retained in raw archive; checksums updated.");
}
